        if any(r.status is Status.SKIP for r in self.results):
            return EXIT_SKIPPED
        return EXIT_OK

    def as_json(self) -> dict[str, Any]:
        return {"exit_code": self.exit_code, "human_commits": self.human_commits,
                "checks": [r.as_dict() for r in self.results]}  # fmt: skip

    def render(self) -> str:
        lines = []
